final class PremiumLibrary {
 final MainActivity a;boolean hideLogged=false;String historyView="Up next",month="All time",status="All",collection="All",type="All",sort="Recent";int diaryLimit=60;
 PremiumLibrary(MainActivity activity){a=activity;}
 void chips(String[] values,String chosen,java.util.function.Consumer<String> action){HorizontalScrollView scroll=new HorizontalScrollView(a);LinearLayout row=new LinearLayout(a);scroll.setHorizontalScrollBarEnabled(false);scroll.addView(row);a.body.addView(scroll);for(String value:values){Button b=a.button(value,()->action.accept(value),value.equals(chosen));LinearLayout.LayoutParams p=new LinearLayout.LayoutParams(-2,a.dp(46));p.setMargins(0,0,a.dp(8),0);row.addView(b,p);}}
 static String month(JSONObject v){long at=DataStore.date(v.optString("watchedAt"));return Instant.ofEpochMilli(at).atZone(ZoneId.systemDefault()).toLocalDate().toString().substring(0,7);}
 void history(){if(historyView.equals("Stats")){a.body.addView(a.button(Loc.f("Your %d story ›",LocalDate.now().getYear()),()->a.startActivity(new android.content.Intent(a,YearStoryActivity.class)),true));a.ui.stats(a.body);extraStats();return;}List<JSONObject> records=new ArrayList<>();TreeSet<String> months=new TreeSet<>(Comparator.reverseOrder());for(JSONObject i:DataStore.objects(a.data.itemsShared()))for(JSONObject v:DataStore.objects(i.optJSONArray("viewings"))){if(hideLogged&&DataStore.backfill(v))continue;JSONObject r=DataStore.copy(v);DataStore.put(r,"item",i);records.add(r);if(!v.optBoolean("dateUnknown"))months.add(month(v));}
  List<String> choices=new ArrayList<>();choices.add("All time");choices.addAll(months);Spinner picker=new Spinner(a);picker.setAdapter(new ArrayAdapter<>(a,android.R.layout.simple_spinner_dropdown_item,choices));picker.setSelection(Math.max(0,choices.indexOf(month)));a.body.addView(picker);picker.setOnItemSelectedListener(new AdapterView.OnItemSelectedListener(){public void onNothingSelected(AdapterView<?> p){}public void onItemSelected(AdapterView<?> p,View view,int n,long id){String value=choices.get(n);if(!month.equals(value)){month=value;diaryLimit=60;a.render();}}});
  records.removeIf(v->!month.equals("All time")&&(v.optBoolean("dateUnknown")||!month(v).equals(month)));records.sort((x,y)->x.optBoolean("dateUnknown")!=y.optBoolean("dateUnknown")?Boolean.compare(x.optBoolean("dateUnknown"),y.optBoolean("dateUnknown")):Long.compare(DataStore.date(y.optString("watchedAt")),DataStore.date(x.optString("watchedAt"))));Set<String> titles=new HashSet<>();double seconds=0;int rewatches=0;for(JSONObject r:records){JSONObject i=r.optJSONObject("item");titles.add(i.optString("group"));seconds+=i.optDouble("duration");long at=DataStore.date(r.optString("watchedAt"));if(DataStore.objects(i.optJSONArray("viewings")).stream().anyMatch(v->DataStore.date(v.optString("watchedAt"))<at))rewatches++;}
  a.paragraph(records.size()+" viewings · "+titles.size()+" titles · "+rewatches+" rewatches\n"+String.format(Locale.ROOT,"%.1f h known runtime",seconds/3600));
  if(historyView.equals("Diary")){chips(new String[]{hideLogged?"✓ Hide logged history":"Hide logged history"},hideLogged?(hideLogged?"✓ Hide logged history":""):"",v->{hideLogged=!hideLogged;diaryLimit=60;a.render();});String day="";int shown=0;for(JSONObject r:records){if(++shown>diaryLimit)break;JSONObject i=r.optJSONObject("item");String date=r.optBoolean("dateUnknown")?"Date unknown":Instant.ofEpochMilli(DataStore.date(r.optString("watchedAt"))).atZone(ZoneId.systemDefault()).toLocalDate().toString();if(!date.equals(day)){a.heading(dayLabel(date));day=date;}a.body.addView(diaryCard(i,r));}if(records.isEmpty())a.paragraph("No viewings in this month.");if(records.size()>diaryLimit)a.body.addView(a.button("Load more viewings",()->{diaryLimit+=60;a.render();},false));return;}
  chips(new String[]{"All","Movies","Shows"},type,v->{type=v;a.render();});chips(new String[]{"Recent","A–Z"},sort,v->{sort=v;a.render();});
  chips(new String[]{"All","Watching","Planned","Finished","Dropped","Unavailable"},status,v->{status=v;a.render();});List<List<JSONObject>> groups=a.groups();groups.removeIf(g->type.equals("Movies")&&!g.get(0).optBoolean("movie")||type.equals("Shows")&&g.get(0).optBoolean("movie"));groups.removeIf(g->g.stream().noneMatch(i->DataStore.watched(i)||MainActivity.position(i)>0)&&!g.get(0).optString("status").equals("Dropped")&&!g.get(0).optString("status").equals("Finished"));groups.removeIf(g->!status.equals("All")&&(status.equals("Unavailable")?g.stream().anyMatch(a::playable):!label(g).equals(status)));if(sort.equals("Recent"))groups.sort((x,y)->Long.compare(MainActivity.recent(y),MainActivity.recent(x)));a.grid(groups,a.body);
 }
 // "Today", "Yesterday", "Friday, 23 October" (with the year once it isn't this year).
 static String dayLabel(String iso){if(iso.length()!=10||iso.charAt(4)!='-')return Loc.t(iso);LocalDate d=LocalDate.parse(iso),today=LocalDate.now();if(d.equals(today))return Loc.t("Today");if(d.equals(today.minusDays(1)))return Loc.t("Yesterday");return d.format(java.time.format.DateTimeFormatter.ofPattern(d.getYear()==today.getYear()?"EEEE, d MMMM":"EEEE, d MMMM yyyy",Loc.arabic?new Locale("ar"):Locale.getDefault()));}
 android.view.View diaryCard(JSONObject i,JSONObject record){LinearLayout row=new LinearLayout(a);row.setPadding(a.dp(14),a.dp(12),a.dp(14),a.dp(12));row.setBackground(MainActivity.bg(MainActivity.PANEL,a.dp(12)));LinearLayout.LayoutParams lp=new LinearLayout.LayoutParams(-1,-2);lp.setMargins(0,0,0,a.dp(10));row.setLayoutParams(lp);row.addView(a.poster(i,true),new LinearLayout.LayoutParams(a.dp(64),a.dp(94)));LinearLayout info=a.column();LinearLayout.LayoutParams ip=new LinearLayout.LayoutParams(0,-2,1);ip.setMargins(a.dp(14),0,0,0);row.addView(info,ip);info.addView(a.text(i.optString("title"),17,MainActivity.WHITE));info.addView(a.text((i.optBoolean("movie")?Loc.t("Movie"):PhoneSmart.label(i)+(i.optString("episodeTitle").isEmpty()?"":" · "+i.optString("episodeTitle")))+" · "+(record.optBoolean("dateUnknown")?Loc.t("Date unknown"):Instant.ofEpochMilli(DataStore.date(record.optString("watchedAt"))).atZone(ZoneId.systemDefault()).toLocalTime().withSecond(0).withNano(0).toString()),12,MainActivity.MUTED));info.addView(a.text(record.optString("source"),11,MainActivity.MUTED));JSONObject review=i.optJSONObject("review");int rating=a.data.rating10(i);boolean liked=a.data.liked(i.optString("group"))||a.data.liked(i.optString("id"));long at=DataStore.date(record.optString("watchedAt"));boolean rewatch=DataStore.objects(i.optJSONArray("viewings")).stream().anyMatch(v->!v.optString("id").equals(record.optString("id"))&&(at==0||DataStore.date(v.optString("watchedAt"))<at));TextView feelings=a.text((liked?"♥  ":"")+(rating>0?PhoneTracker.stars(rating):Loc.t("☆ Quick rate"))+(rewatch?"  ↻":""),15,MainActivity.GOLD);feelings.setOnClickListener(v->PhoneTracker.quickRate(a,i));info.addView(feelings);if(review!=null&&!review.optString("note").isEmpty()){TextView note=a.text(review.optString("note"),13,MainActivity.WHITE);note.setMaxLines(3);note.setEllipsize(android.text.TextUtils.TruncateAt.END);info.addView(note);}info.addView(a.text(Loc.t("Details · hold to edit date or delete"),12,MainActivity.GOLD));row.setOnClickListener(v->a.options(i));row.setOnLongClickListener(v->{Motion.haptic(v);ViewingEditor.open(a,i.optString("id"),record.optString("id"),a::render);return true;});Motion.card(row);return row;}
 String label(List<JSONObject> group){String manual=group.get(0).optString("status");if(!manual.isEmpty()&&!manual.equals("Automatic"))return manual;if(group.stream().allMatch(DataStore::watched))return "Finished";return group.stream().anyMatch(i->DataStore.watched(i)||MainActivity.position(i)>0)?"Watching":"Planned";}
 void status(JSONObject i){String[] labels={"Automatic","Watching","Planned","Finished","Dropped"};new AlertDialog.Builder(a).setTitle("Viewing status").setItems(labels,(d,n)->{JSONObject op=a.data.operation(i.optString("id"),"status");DataStore.put(op,"status",labels[n]);a.data.queue(op);a.data.syncSoon();a.render();}).show();}
 boolean member(JSONObject i,String name){JSONArray members=i.optJSONArray("collections");if(members!=null)for(int n=0;n<members.length();n++)if(members.optString(n).equals(name))return true;return false;}
 void collections(JSONObject i){JSONArray list=a.browsingSettings().optJSONArray("collections");List<String> names=new ArrayList<>();if(list!=null)for(int n=0;n<list.length();n++)names.add(list.optString(n));names.add("+ New collection");new AlertDialog.Builder(a).setTitle("Save to collection").setItems(names.toArray(new String[0]),(d,n)->{if(n==names.size()-1){EditText input=new EditText(a);input.setHint("Collection name");new AlertDialog.Builder(a).setTitle("New collection").setView(input).setNegativeButton("Cancel",null).setPositiveButton("Create",(dialog,w)->change(i,input.getText().toString().trim(),true)).show();}else change(i,names.get(n),!member(i,names.get(n)));}).show();}
 void change(JSONObject i,String name,boolean value){if(name.isEmpty()||name.length()>60||name.equals("All")||name.equals("My List")){a.toast("Use a name with 1–60 characters.");return;}JSONObject op=a.data.operation(i.optString("id"),"collection");DataStore.put(op,"name",name);DataStore.put(op,"value",value);a.data.queue(op);a.data.syncSoon();a.render();a.toast(value?"Saved to "+name:"Removed from "+name);}
 void match(JSONObject i){LinearLayout panel=a.column();panel.setPadding(a.dp(20),0,a.dp(20),0);String[] labels={"Title","Year","IMDb ID (optional)","Season","Episode"},keys={"title","year","imdb","season","episode"};EditText[] inputs=new EditText[5];for(int n=0;n<5;n++){EditText input=new EditText(a);input.setHint(labels[n]);input.setText(i.optString(keys[n]));panel.addView(input);inputs[n]=input;}CheckBox whole=new CheckBox(a);whole.setText("Apply title and season offset to the whole show");whole.setChecked(!i.optBoolean("movie"));panel.addView(whole);ScrollView scroll=new ScrollView(a);scroll.addView(panel);AlertDialog dialog=new AlertDialog.Builder(a).setTitle("Correct match · history stays intact").setView(scroll).setNegativeButton("Cancel",null).setPositiveButton("Save",null).create();dialog.setOnShowListener(d->dialog.getButton(AlertDialog.BUTTON_POSITIVE).setOnClickListener(v->{try{String title=inputs[0].getText().toString().trim(),imdb=inputs[2].getText().toString().trim();int year=Integer.parseInt(inputs[1].getText().toString()),season=Integer.parseInt(inputs[3].getText().toString()),episode=Integer.parseInt(inputs[4].getText().toString());if(title.isEmpty()||title.length()>200||year<0||year>2100||season<0||season>1000||episode<0||episode>10000||!imdb.isEmpty()&&!imdb.matches("tt[0-9]+"))throw new IllegalArgumentException();for(JSONObject other:DataStore.objects(a.data.itemsShared()))if(other.optString("group").equals(i.optString("group"))){if(whole.isChecked()&&other.optInt("season")+season-i.optInt("season")<0)throw new IllegalArgumentException();if(!whole.isChecked()&&!other.optString("id").equals(i.optString("id"))&&other.optInt("season")==season&&other.optInt("episode")==episode)throw new IllegalArgumentException();}JSONObject op=a.data.operation(i.optString("id"),"match");DataStore.put(op,"title",title);DataStore.put(op,"year",year);DataStore.put(op,"imdb",imdb);DataStore.put(op,"season",season);DataStore.put(op,"episode",episode);DataStore.put(op,"value",whole.isChecked());a.data.queue(op);a.data.syncSoon();dialog.dismiss();a.render();a.toast("Correction saved. Syncs with your PC.");}catch(Exception e){inputs[0].setError("Check the fields and episode numbers.");}}));dialog.show();}
 void filter(){List<String> names=new ArrayList<>(Arrays.asList("All","My List"));JSONArray list=a.browsingSettings().optJSONArray("collections");if(list!=null)for(int n=0;n<list.length();n++)names.add(list.optString(n));if(names.size()>2)names.add(Loc.t("✎ Manage"));chips(names.toArray(new String[0]),collection,v->{if(v.equals(Loc.t("✎ Manage"))){manageCollections();return;}collection=v;a.render();});}
 void manageCollections(){JSONArray list=a.browsingSettings().optJSONArray("collections");List<String> names=new ArrayList<>();if(list!=null)for(int n=0;n<list.length();n++)names.add(list.optString(n));if(names.isEmpty())return;new AlertDialog.Builder(a).setTitle(Loc.t("Your collections")).setItems(names.toArray(new String[0]),(d,w)->{String name=names.get(w);EditText input=new EditText(a);input.setText(name);input.setSelectAllOnFocus(true);new AlertDialog.Builder(a).setTitle(name).setView(input).setPositiveButton(Loc.t("Rename"),(d2,w2)->{String next=input.getText().toString().trim();if(next.isEmpty()||next.length()>60||next.equals("All")||next.equals("My List")||next.equals(name))return;a.data.renameCollection(name,next);if(collection.equals(name))collection=next;a.render();}).setNeutralButton(Loc.t("Delete"),(d2,w2)->new AlertDialog.Builder(a).setMessage(Loc.f("Delete the collection \"%s\"? Titles stay in your library.",name)).setPositiveButton(Loc.t("Delete"),(d3,w3)->{a.data.deleteCollection(name);if(collection.equals(name))collection="All";a.render();}).setNegativeButton(Loc.t("Cancel"),null).show()).setNegativeButton(Loc.t("Cancel"),null).show();}).show();}
 void extras(){JSONArray queue=a.data.playQueue();if(queue.length()>0){a.heading("Your play queue");for(int n=0;n<queue.length();n++){JSONObject i=a.data.item(queue.optString(n));if(i==null)continue;a.body.addView(a.button(i.optString("title")+" · "+MainActivity.episode(i)+" · Options",()->new AlertDialog.Builder(a).setItems(new String[]{"Play","Remove from queue","Move earlier","Move later"},(d,w)->{if(w==0)a.play(i,false);else{if(w==1)a.data.consumeVideo(i.optString("id"));else a.data.moveVideo(i.optString("id"),w==2?-1:1);a.render();}}).show(),false));}}
  List<List<JSONObject>> added=a.groups();added.removeIf(g->g.stream().noneMatch(i->DataStore.date(i.optString("addedAt"))>0));added.sort((x,y)->Long.compare(y.stream().mapToLong(i->DataStore.date(i.optString("addedAt"))).max().orElse(0),x.stream().mapToLong(i->DataStore.date(i.optString("addedAt"))).max().orElse(0)));a.ui.rail(a.body,"Recently added","",a.posters(added,16),null);
  a.ui.comingUp(a.body);
 }
 public static java.util.function.Function<String,List<String>> PeopleFor;
 void extraStats(){Map<String,Double> decades=new TreeMap<>(),languages=new TreeMap<>(),people=new HashMap<>();for(JSONObject item:DataStore.objects(a.data.itemsShared())){int views=DataStore.objects(item.optJSONArray("viewings")).size();if(views==0)continue;double hours=Math.max(0,item.optDouble("duration"))*views/3600;int year=item.optInt("year");if(year>1800)decades.merge((year/10*10)+"s",hours,Double::sum);String language=item.optString("language",item.optString("originalLanguage"));if(!language.isEmpty()&&!language.equals("null"))languages.merge(language,hours,Double::sum);if(PeopleFor!=null)try{List<String> names=PeopleFor.apply(item.optString("imdb"));if(names!=null)for(String name:names)if(name!=null&&!name.isEmpty())people.merge(name,hours,Double::sum);}catch(Exception ignored){}}statsBars("By decade",decades);statsBars("By language",languages);statsBars("By people",people);}
 void statsBars(String label,Map<String,Double> values){if(values.isEmpty())return;a.heading(Loc.t(label));List<Map.Entry<String,Double>> entries=new ArrayList<>(values.entrySet());entries.sort((x,y)->Double.compare(y.getValue(),x.getValue()));double max=Math.max(.001,entries.get(0).getValue());for(Map.Entry<String,Double> e:entries.subList(0,Math.min(6,entries.size())))a.body.addView(a.ui.meter(e.getKey(),e.getValue()/max,Loc.f("%.1f h",e.getValue())));}

}
